const envelope = $input.first().json || {};
const body = envelope.body && typeof envelope.body === 'object' ? envelope.body : {};
const config = {
  dry_run: true,
  suppression_endpoint_url: 'https://CONFIGURE-ME.invalid/suppression/upsert',
  crm_endpoint_url: 'https://CONFIGURE-ME.invalid/crm/outreach-event'
};
const clean = (value, max = 500) => String(value ?? '').trim().replace(/\s+/g, ' ').slice(0, max);
const aliases = { auto_reply_received: 'reply_received', email_reply_received: 'reply_received', bounce: 'email_bounced', unsubscribed: 'lead_unsubscribed' };
const rawType = clean(body.event_type || body.type, 100).toLowerCase();
const eventType = aliases[rawType] || rawType;
const supported = new Set(['reply_received', 'email_bounced', 'lead_unsubscribed']);
const leadEmail = clean(body.lead_email || body.email, 254).toLowerCase();
const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(leadEmail);
const occurredAt = clean(body.timestamp || body.created_at, 80) || new Date().toISOString();
const seed = `${clean(body.id || body.webhook_event_id, 180)}|${eventType}|${leadEmail}|${occurredAt}|${clean(body.campaign_id, 100)}`;
let hash = 2166136261;
for (let i = 0; i < seed.length; i++) { hash ^= seed.charCodeAt(i); hash = Math.imul(hash, 16777619); }
const eventKey = clean(body.id || body.webhook_event_id, 180) || `inst_evt_${(hash >>> 0).toString(16).padStart(8, '0')}`;
const reasons = [];
if (!supported.has(eventType)) reasons.push(`Unsupported event_type: ${rawType || 'missing'}`);
if (!emailValid) reasons.push('Missing or invalid lead_email');
return [{ json: {
  valid: reasons.length === 0,
  validation_reasons: reasons,
  event_key: eventKey,
  event_type: eventType,
  occurred_at: occurredAt,
  lead_email: leadEmail,
  campaign_id: clean(body.campaign_id, 100),
  campaign_name: clean(body.campaign_name, 200),
  workspace_id: clean(body.workspace || body.workspace_id, 100),
  unibox_url: clean(body.unibox_url, 500),
  requires_suppression: eventType === 'email_bounced' || eventType === 'lead_unsubscribed',
  suppression_reason: eventType === 'email_bounced' ? 'hard_or_provider_bounce' : eventType === 'lead_unsubscribed' ? 'unsubscribe' : '',
  crm_status: eventType === 'reply_received' ? 'replied' : eventType === 'email_bounced' ? 'bounced' : eventType === 'lead_unsubscribed' ? 'unsubscribed' : 'unknown',
  config
} }];
